/* global AlfaPwaPolicies, caches, clients, fetch, Headers, Request, Response, URL */

importScripts("/sw-policies.js");

const SW_VERSION = __SW_VERSION__;
const PRECACHE_URLS = __PRECACHE_URLS__;
const INJECTED_API_ORIGINS = __API_ORIGINS__;
const IS_DEV = __IS_DEV__;

const P = self.AlfaPwaPolicies;
const CACHES = P.getCacheNames(SW_VERSION);
const OFFLINE_URL = P.OFFLINE_URL;
const IMAGE_PLACEHOLDER = Uint8Array.from(
  atob(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==",
  ),
  (character) => character.charCodeAt(0),
);

let allowedApiOrigins = new Set(
  [self.location.origin].concat(Array.isArray(INJECTED_API_ORIGINS) ? INJECTED_API_ORIGINS : []),
);

const imageRevalidations = new Map();

self.__ALFA_PWA_VERSION__ = SW_VERSION;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHES.precache);
      await Promise.all(
        PRECACHE_URLS.map(async (url) => {
          try {
            const request = new Request(url, { cache: "reload" });
            const response = await fetch(request);
            if (response && response.ok) {
              await cache.put(request, response);
            }
          } catch (error) {
            console.warn("[Alfa PWA] Precache failed for", url, error);
          }
        }),
      );

      // First installation should be available immediately. For an update an
      // active worker already exists, so we intentionally keep the new worker
      // waiting until the user accepts the update.
      if (!self.registration.active) {
        await self.skipWaiting();
      }
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set(Object.keys(CACHES).map((key) => CACHES[key]));
      const cacheNames = await caches.keys();
      await Promise.all(
        cacheNames.map(async (name) => {
          if (P.isManagedCacheName(name) && !keep.has(name)) {
            await caches.delete(name);
          }
        }),
      );

      if (self.registration.navigationPreload) {
        try {
          await self.registration.navigationPreload.enable();
        } catch (error) {
          console.warn("[Alfa PWA] Navigation preload could not be enabled", error);
        }
      }

      await self.clients.claim();
    })(),
  );
});

self.addEventListener("message", (event) => {
  const data = event.data || {};

  if (data.type === "SKIP_WAITING") {
    event.waitUntil(self.skipWaiting());
    return;
  }

  if (data.type === "CONFIGURE") {
    const origins = Array.isArray(data.apiOrigins) ? data.apiOrigins : [];
    const validOrigins = origins.filter((origin) => {
      try {
        const parsed = new URL(origin);
        return parsed.protocol === "https:" || parsed.protocol === "http:";
      } catch {
        return false;
      }
    });
    allowedApiOrigins = new Set([self.location.origin].concat(validOrigins));
    return;
  }

  if (data.type === "CLEAR_USER_DATA") {
    event.waitUntil(clearUserScopedCaches());
    return;
  }

  if (data.type === "INVALIDATE_CATALOG") {
    event.waitUntil(invalidateCatalogCaches());
    return;
  }

  if (data.type === "GET_VERSION") {
    const port = event.ports && event.ports[0];
    if (port) port.postMessage({ version: SW_VERSION });
  }
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (!request || request.method !== "GET") return;

  let url;
  try {
    url = new URL(request.url);
  } catch {
    return;
  }

  if (url.protocol !== "http:" && url.protocol !== "https:") return;
  if (request.headers.has("range")) return;

  // Reachability probes must bypass Cache Storage and always use the network.
  if (P.isPwaHealthCheck(url)) return;

  const isSameOrigin = url.origin === self.location.origin;
  const hasAuthorization = request.headers.has("authorization");

  if (P.isApiRequest(url.pathname)) {
    if (!allowedApiOrigins.has(url.origin)) return;
    if (hasAuthorization) return;
    const policy = P.getApiCachePolicy(url.pathname, request.method);
    if (!policy) return;
    event.respondWith(apiStrategy(event, policy));
    return;
  }

  if (P.isRscRequest(request.headers, url.search)) return;

  if (request.mode === "navigate" || request.destination === "document") {
    if (!isSameOrigin) return;
    event.respondWith(navigationStrategy(event));
    return;
  }

  if (hasAuthorization) return;

  if (IS_DEV && url.pathname.indexOf("/_next/") === 0) return;

  if (P.isFontRequest(url.pathname, request.destination)) {
    if (!allowedApiOrigins.has(url.origin)) return;
    event.respondWith(cacheFirstStrategy(event, CACHES.fonts, P.CACHE_LIMITS.fonts));
    return;
  }

  if (P.isStaticAsset(url.pathname)) {
    if (!allowedApiOrigins.has(url.origin)) return;
    event.respondWith(staticAssetStrategy(event));
    return;
  }

  if (P.isImageRequest(url.pathname, request.destination)) {
    if (!allowedApiOrigins.has(url.origin)) return;
    event.respondWith(imageStrategy(event));
  }
});

async function staticAssetStrategy(event) {
  const request = event.request;
  const precached = await caches.match(request, { cacheName: CACHES.precache });
  if (precached) return precached;
  return cacheFirstStrategy(event, CACHES.static, P.CACHE_LIMITS.static);
}

async function cacheFirstStrategy(event, cacheName, maxEntries) {
  const request = event.request;
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (P.isCacheableResponse(response)) {
    try {
      await cache.put(request, response.clone());
      await enforceLimit(cache, maxEntries);
    } catch (error) {
      console.warn("[Alfa PWA] Static cache write failed", error);
    }
  }
  return response;
}

async function navigationStrategy(event) {
  const request = event.request;
  const url = new URL(request.url);
  const canUseCache = P.shouldCachePage(
    url.pathname,
    request.headers.has("authorization"),
  );

  let networkResponse;
  try {
    if (event.preloadResponse) {
      try {
        networkResponse = await event.preloadResponse;
      } catch {
        networkResponse = undefined;
      }
    }
    if (!networkResponse) {
      networkResponse = await fetch(request);
    }
  } catch {
    return cachedPageOrOffline(request, canUseCache);
  }

  if (networkResponse.status >= 500 && canUseCache) {
    const cached = await matchCachedPage(request);
    if (cached) return cached;
  }

  if (
    canUseCache &&
    P.isCacheableNavigationResponse(networkResponse, request.url) &&
    P.isCacheablePublicPageResponse(networkResponse)
  ) {
    try {
      const cache = await caches.open(CACHES.pages);
      await cache.put(request, networkResponse.clone());
      await enforceLimit(cache, P.CACHE_LIMITS.pages);
    } catch (error) {
      console.warn("[Alfa PWA] Page cache write failed", error);
    }
  }

  return networkResponse;
}

async function cachedPageOrOffline(request, canUseCache) {
  if (canUseCache) {
    const cached = await matchCachedPage(request);
    if (cached) return cached;
  }
  return offlineFallback();
}

async function matchCachedPage(request) {
  const cache = await caches.open(CACHES.pages);
  const exact = await cache.match(request);
  if (exact) return exact;

  try {
    return (await cache.match(request, { ignoreSearch: true })) || undefined;
  } catch {
    return undefined;
  }
}

async function offlineFallback() {
  const precached = await caches.match(OFFLINE_URL, {
    cacheName: CACHES.precache,
  });
  if (precached) return precached;

  const anywhere = await caches.match(OFFLINE_URL);
  if (anywhere) return anywhere;

  return new Response(
    "<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>غير متصل</title></head><body style=\"font-family:Tahoma,Arial,sans-serif;background:#f6f5f8;color:#1f2937;display:flex;min-height:100vh;align-items:center;justify-content:center;text-align:center;padding:24px\"><main><h1>أنت غير متصل بالإنترنت</h1><p>يمكنك فتح الصفحات التي زرتها سابقًا. يلزم الاتصال بالإنترنت لإتمام الطلبات والدفع.</p><p><a href=\"/\">إعادة المحاولة</a></p><p dir=\"ltr\">You are offline. Checkout and payments require an internet connection.</p></main></body></html>",
    {
      status: 200,
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-store",
      },
    },
  );
}

async function apiStrategy(event, policy) {
  const request = event.request;
  const cache = await caches.open(CACHES[policy.cacheKind]);
  const language = P.getRequestLanguage(request.headers);
  const cacheKey = P.buildApiCacheKey(request.url, language);
  const cached = await cache.match(cacheKey);
  const cachedAt = Number(
    (cached && cached.headers.get("x-alfa-cached-at")) || 0,
  );
  const isFresh = Boolean(cached) && Date.now() - cachedAt < policy.maxAgeMs;

  if (isFresh) return cached;

  let response;
  try {
    response = await fetchWithTimeout(request, cached ? 6000 : 0);
  } catch (error) {
    if (cached) return cached;
    throw error;
  }

  if (P.isCacheableResponse(response)) {
    try {
      const stamped = await stampResponse(response.clone());
      await cache.put(cacheKey, stamped);
      await enforceLimit(cache, policy.trimTo);
    } catch (error) {
      console.warn("[Alfa PWA] API cache write failed", error);
    }
    return response;
  }

  if (cached && response.status >= 500) return cached;
  return response;
}

async function imageStrategy(event) {
  const request = event.request;
  const precached = await caches.match(request, { cacheName: CACHES.precache });
  if (precached) return precached;

  const cache = await caches.open(CACHES.images);
  const cached = await cache.match(request);

  if (cached) {
    const cachedAt = Number(cached.headers.get("x-alfa-cached-at") || 0);
    const isStale = Date.now() - cachedAt > 24 * 60 * 60 * 1000;
    if (isStale && !imageRevalidations.has(request.url)) {
      const revalidation = fetch(request)
        .then(async (response) => {
          if (P.isCacheableResponse(response)) {
            const stamped = await stampResponse(response.clone());
            await cache.put(request, stamped);
            await enforceLimit(cache, P.CACHE_LIMITS.images);
          }
        })
        .catch(() => {})
        .finally(() => imageRevalidations.delete(request.url));
      imageRevalidations.set(request.url, revalidation);
      // The cached image is returned immediately. The refresh is best-effort;
      // it must not delay response or rely on waitUntil after an await.
      void revalidation;
    }
    return cached;
  }

  try {
    const response = await fetch(request);
    if (P.isCacheableResponse(response)) {
      try {
        const stamped = await stampResponse(response.clone());
        await cache.put(request, stamped);
        await enforceLimit(cache, P.CACHE_LIMITS.images);
      } catch (error) {
        console.warn("[Alfa PWA] Image cache write failed", error);
      }
    }
    return response;
  } catch (error) {
    return new Response(IMAGE_PLACEHOLDER, {
      status: 200,
      headers: {
        "Content-Type": "image/png",
        "Cache-Control": "no-store",
      },
    });
  }
}

async function stampResponse(response) {
  const headers = new Headers(response.headers);
  headers.delete("content-encoding");
  headers.delete("content-length");
  headers.delete("transfer-encoding");
  headers.set("x-alfa-cached-at", String(Date.now()));
  const body = await response.blob();
  return new Response(body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

async function fetchWithTimeout(request, timeoutMs) {
  if (!timeoutMs) return fetch(request);

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(request, { signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

async function enforceLimit(cache, maxEntries) {
  if (!maxEntries || maxEntries < 1) return;
  const keys = await cache.keys();
  if (keys.length <= maxEntries) return;
  const removeCount = keys.length - maxEntries;
  for (let index = 0; index < removeCount; index += 1) {
    await cache.delete(keys[index]);
  }
}

async function clearUserScopedCaches() {
  await Promise.all([
    caches.delete(CACHES.pages),
    caches.delete(CACHES.publicApi),
  ]);
}

async function invalidateCatalogCaches() {
  await Promise.all([
    caches.delete(CACHES.pages),
    caches.delete(CACHES.publicApi),
    caches.delete(CACHES.images),
  ]);
}
